mapper.select:
SELECT id, end_time AS candidate_time FROM screening
WHERE status IN (0, 1, 2) AND end_time <= #{now}

    AND (end_time > #{afterTime} OR (end_time = #{afterTime} AND id > #{afterId}))

ORDER BY end_time, id LIMIT #{limit}

SELECT id, sale_end_time AS candidate_time FROM screening
WHERE status IN (0, 1) AND sale_end_time <= #{now} AND end_time > #{now}

    AND (sale_end_time > #{afterTime} OR (sale_end_time = #{afterTime} AND id > #{afterId}))

ORDER BY sale_end_time, id LIMIT #{limit}

SELECT s.id, s.sale_start_time AS candidate_time FROM screening s JOIN movie m ON m.id = s.movie_id AND m.status = 0 JOIN hall h ON h.id = s.hall_id AND h.status = 0 WHERE s.status = 0 AND s.sale_start_time <= #{now} AND s.sale_end_time > #{now} AND s.end_time > #{now} AND DATE(s.start_time) >= m.release_date AND EXISTS (SELECT 1 FROM screening_seat ss JOIN seat st ON st.id = ss.seat_id AND st.hall_id = s.hall_id AND st.status = 0 WHERE ss.screening_id = s.id AND ss.status = 0 AND ss.order_id IS NULL)
AND (s.sale_start_time > #{afterTime} OR (s.sale_start_time = #{afterTime} AND s.id > #{afterId}))
ORDER BY s.sale_start_time, s.id LIMIT #{limit}
